let statements = []
for (const item of $input.all()) {

  item.json.from?.forEach((emailOrigin, index) => {
    const textContent = item.json.text[index]?.split('\n').join(' ');
    const cleanTextContent = removeHtmlCssScript(textContent)
    const cleanDate = new Date().toDateString()
    statements.push('[[' + emailOrigin + ']] ' + '[' + cleanDate + '] ' + cleanTextContent)
  })
}

return { statements: statements }

function removeHtmlCssScript(text) {
  if (!text || typeof text !== 'string') {
    return '';
  }

  let cleanText = text;

  // Remove script tags and their content (case insensitive)
  cleanText = cleanText.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');

  // Remove style tags and their content (case insensitive)
  cleanText = cleanText.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');

  // Remove HTML comments
  cleanText = cleanText.replace(/<!--[\s\S]*?-->/g, '');

  // Remove all remaining HTML tags
  cleanText = cleanText.replace(/<[^>]*>/g, '');

  // Decode common HTML entities
  const htmlEntities = {
    '&amp;': '&',
    '&lt;': '<',
    '&gt;': '>',
    '&quot;': '"',
    '&#39;': "'",
    '&nbsp;': ' ',
    '&copy;': '©',
    '&reg;': '®',
    '&trade;': '™'
  };

  Object.keys(htmlEntities).forEach(entity => {
    const regex = new RegExp(entity, 'g');
    cleanText = cleanText.replace(regex, htmlEntities[entity]);
  });

  // Clean up extra whitespace
  cleanText = cleanText.replace(/\s+/g, ' ').trim();

  return cleanText;
}"}, "position": [1200, 200], "type": "n8n-nodes-base.code", "typeVersion": 2}, {"credentials": {"googlePalmApi": {"id": "ivswOFTY8MYDbj5b", "name": "Google Gemini(PaLM) Api account"}}, "id": "599264b8-bd89-4ed9-8645-725ebd005747", "name": "Google Gemini Chat Model", "parameters": {"modelName": "models/gemini-2.5-flash-preview-04-17", "options": {}}, "position": [120, 500], "type": "@n8n/n8n-nodes-langchain.lmChatGoogleGemini", "typeVersion": 1}, {"id": "e7251d9c-e247-4b48-a7db-4b7bba057777", "name": "Was label provided?", "parameters": {"conditions": {"combinator": "and", "conditions": [{"id": "a8278945-a9a1-45c6-809f-b9282f6de0ed", "leftValue": "={{ $('Assign Processing Settings').item.json["Label Filter"] }}", "operator": {"operation": "notEmpty", "singleValue": true, "type": "string"}, "rightValue": ""}], "options": {"caseSensitive": true, "leftValue": "", "typeValidation": "strict", "version": 2}}, "options": {}}, "position": [-1080, 320], "type": "n8n-nodes-base.if", "typeVersion": 2.2}, {"id": "6a1fdf73-fa60-46d6-8980-e192735fbb54", "name": "Should analyze snippets?", "parameters": {"conditions": {"combinator": "and", "conditions": [{"id": "802f2028-04bb-43ad-befa-416c0afc5515", "leftValue": "={{ $('Assign Processing Settings').item.json['Analyze Full Email Text?'] }}", "operator": {"operation": "empty", "singleValue": true, "type": "string"}, "rightValue": "Snippets"}], "options": {"caseSensitive": true, "leftValue": "", "typeValidation": "strict", "version": 2}}, "options": {}}, "position": [-620, 380], "type": "n8n-nodes-base.if", "typeVersion": 2.2}, {"id": "daa2cf5f-e8b5-45a4-ab73-feb5981d665d", "name": "Should analyze snippets from filtered emails?", "parameters": {"conditions": {"combinator": "and", "conditions": [{"id": "82abd9a8-375b-4c3f-8f19-be6b3c1b8e80", "leftValue": "={{ $('Assign Processing Settings').item.json['Analyze Full Email Text?'] }}", "operator": {"operation": "empty", "singleValue": true, "type": "string"}, "rightValue": "Snippets"}],