  }
}];"}, "position": [464, -48], "type": "n8n-nodes-base.code", "typeVersion": 2}, {"id": "d4f77e57-f872-47e9-a49f-307f0da3aa50", "name": "model prices", "parameters": {"include": "selected", "includeFields": "standardize_names_dic, models_used", "includeOtherFields": true, "jsonOutput": "{
