  const bbLower = bbMid.map((m,i)=> m!=null ? m - BB_K*bbStd[i] : null);

  const { plusDI, minusDI, ADX } = adx(highs, lows, closes, ADX_PERIOD);

  // last
  const i = N - 1;
  const price = closes[i];
  const last = {
    price,
    rsi14: rsi14[i],
    macd: macdLine[i],
    macdSignal: macdSignal[i],
    macdHist: macdHist[i],
    bbUpper: bbUpper[i],
    bbMid: bbMid[i],
    bbLower: bbLower[i],
    sma20: sma20[i],
    ema50: ema50[i],
    ema200: ema200[i],
