  min = Math.ceil(min); // 向上取整，确保 min 是整数
  max = Math.floor(max); // 向下取整，确保 max 是整数

  // 兼容处理：如果 min 大于 max，则交换它们的值。
  if (min > max) {
    [min, max] = [max, min]; // 使用数组解构交换值，更简洁
  }

  // 生成随机数。
  return Math.floor(Math.random() * (max - min + 1)) + min;
}
