c0479", "name": "Icebreaker", "type": "string", "value": "={{ $('Icebreaker Writer').item.json.message.content }}"}, {"id": "c94f9c56-ad9a-4672-86ba-e7c08af05adb", "name": "Subject Line", "type": "string", "value": "={{ $json.message.content }}"}]}, "options": {}}, "position": [800, 304], "type": "n8n-nodes-base.set", "typeVersion": 3.4}, {"id": "9aaff82c-d078-4e30-b144-f736d98b00df", "name": "HTTP -> Plain Text", "parameters": {"jsCode": "// HTML to Plain Text Converter for n8n Code Node
// This code takes HTML content and converts it to clean plain text

// Get the HTML content from the previous node
// Adjust the field name based on your input data structure
const htmlContent = $input.first().json.data

if (!htmlContent) {
  return [{ json: { error: "No HTML content found in input" } }];
}

// Function to strip HTML tags and decode HTML entities
function htmlToPlainText(html) {
  let text = html;

  // Remove script and style elements completely
  text = text.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
  text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');

  // Replace common block elements with line breaks
  text = text.replace(/<\/?(div|p|br|h[1-6]|li|tr)[^>]*>/gi, '\n');

  // Replace list items with bullet points
  text = text.replace(/<li[^>]*>/gi, '• ');

  // Remove all remaining HTML tags
  text = text.replace(/<[^>]*>/g, '');

  // Decode common HTML entities
  const entityMap = {
    '&amp;': '&',
    '&lt;': '<',
    '&gt;': '>',
    '&quot;': '"',
    '&#39;': "'",
    '&apos;': "'",
    '&nbsp;': ' ',
    '&copy;': '©',
    '&reg;': '®',
    '&trade;': '™',
    '&hellip;': '...',
    '&mdash;': '—',
    '&ndash;': '–'
  };

  for (const [entity, char] of Object.entries(entityMap)) {
    text = text.replace(new RegExp(entity, 'g'), char);
  }

  // Decode numeric HTML entities (e.g., &#123;)
  text = text.replace(/&#(\d+);/g, (match, dec) => {
    return String.fromCharCode(dec);
  });

  // Decode hex HTML entities (e.g., &#x1F;)
  text = text.replace(/&#x([0-9A-Fa-f]+);/g, (match, hex) => {
    return String.fromCharCode(parseInt(hex, 16));
  });

  // Clean up whitespace
  text = text.replace(/\n\s*\n/g, '\n\n'); // Remove excessive line breaks
  text = text.replace(/[ \t]+/g, ' '); // Replace multiple spaces/tabs with single space
  text = text.trim(); // Remove leading/trailing whitespace

  return text;
}

try {
  const plainText = htmlToPlainText(htmlContent);

  return [{
    json: {
      originalHtml: htmlContent,
      plainText: plainText,
      characterCount: plainText.length,
      wordCount: plainText.split(/\s+/).filter(word => word.length > 0).length,
      success: true
    }
  }];

} catch (error) {
  return [{
    json: {
      error: `Failed to convert HTML to text: ${error.message}`,
      originalHtml: htmlContent,
      success: false
    }
  }];
}"}, "position": [752, -256], "type": "n8n-nodes-base.code", "typeVersion": 2}, {"id": "b329a42d-1cc3-4b61-b567-e3d834e7d75a", "name": "Crawl Website Content", "onError": "continueRegularOutput", "parameters": {"options": {}, "url": "={{ $json.organization_website_url }}"}, "position": [528, -256], "type": "n8n-nodes-base.httpRequest", "typeVersion": 4.2}, {"id": "453c94dc-3f83-4872-85df-48b84e2291cb", "name": "Send a message", "parameters": {"otherOptions": {}}, "position": [608, -624], "type": "n8n-nodes-base.slack", "typeVersion": 2.3, "webhookId": "210406a4-6d26-42d6-8164-fe0c84be50dd"}], "pinData": {}, "settings": {"executionOrder": "v1"}, "tags": [{"createdAt": "2025-07-16T17:56:49.888Z", "id": "Gn50itWF7nQz4HWE", "name": "Advetica AI Automations", "updatedAt": "2025-07-16T17:56:49.888Z"}, {"createdAt": "2025-07-31T13:58:06.976Z", "id": "Ki43TEjHd7EDcykZ", "name": "My Templates", "updatedAt": "2025-07-31T13:58:06.976Z"}], "versionId": "91b75e6f-10e5-4e2f-9ef3-04a81cfadd97"}

