}}];"}, "position": [368, -96], "type": "n8n-nodes-base.code", "typeVersion": 2}, {"id": "fe0422c4-be3e-4a41-aa36-0e631c4450b4", "name": "Append Results to Sheet", "parameters": {"columns": {"attemptToConvertTypes": false, "convertFieldsToString": false, "mappingMode": "autoMapInputData", "matchingColumns": [], "schema": [], "value": {}}, "documentId": {"__rl": true, "cachedResultName": "Competitor tracker", "cachedResultUrl": "https://docs.google.com/spreadsheets/d/1VXVbyqRPPHgO0tyoxpEajCyPX1DZdY3hRu_jCOdDriE/edit?usp=drivesdk", "mode": "list", "value": "1VXVbyqRPPHgO0tyoxpEajCyPX1DZdY3hRu_jCOdDriE"}, "operation": "append", "options": {}, "sheetName": {"__rl": true, "cachedResultName": "Competitor Results", "cachedResultUrl": "https://docs.google.com/spreadsheets/d/1VXVbyqRPPHgO0tyoxpEajCyPX1DZdY3hRu_jCOdDriE/edit#gid=1113333162", "mode": "list", "value": 1113333162}}, "position": [640, -96], "type": "n8n-nodes-base.googleSheets", "typeVersion": 4.6}], "pinData": {}}

