  // Clean title (remove tags like [PDF][B])
  let title = titles[i].replace(/\[.*?\]/g, '').trim();

  // Clean author (remove any trailing dashes or HTML leftovers)
  let author = authors[i] ? authors[i].replace(/\s*-\s*.*/, '').trim() : '';

  // Abstract fallback
  let abstract = abstracts[i] || '';

  // Get PDF link — from either a single object or array of duplicates
  let linkObj = pdfLinks[i];
  let pdfLink = '';

  if (Array.isArray(linkObj)) {
    // If multiple objects per item
    pdfLink = linkObj.find(obj => obj.href)?.href || '';
  } else if (linkObj?.href) {
    pdfLink = linkObj.href;
  }

  // Push cleaned object
  output.push({
    json: {
      title,
      author,
      abstract,
      pdfLink
    }
  });
}

return output;
